    "chunk_id": "41acfa276823a59c",
    "chunk_text": "\n}}显示效果如图 2-73 所示。图 2-73 设置布局总列数后的显示效果当 columns 为自定义值时，栅格布局在任何尺寸设备下都被分为 columns 列。在文件 2-53 中，分别设置栅格布局列数为 4 和 8，子元素默认占一列。文件 2-53 Demo0603.etsimport { promptAction } from '@kit.ArkUI';import { BusinessError } from '@kit.BasicServicesKit';// 使用 Record 类型数据设置边框样式let BorderWH: Record<string, Color | number> = { 'color': Color.Blue, 'width': 2 }@Entry@Componentstruct GridSample {  @State  bgColors: Color[] = [    Color.Red, Color.Orange, Color.Yellow,    Color.Green, Color.Pink, Color.Grey,    Color.Blue, Color.Brown  ]  build() {    Column() {      Row() {        // 栅格行组件，设置一行显示 4 列        GridRow({ columns: 4 }) {          ForEach(this.bgColors, (item: Color, index?: number | undefined) => {            GridCol() {              Row() {                Text(`${index}`)              }.width('100%').height('50')            }.backgroundColor(item)          })        }.width('100%').height('100%')      }.height(160).border(BorderWH).width('90%')      Row() {        // 栅格行组件，设置一行显示 8 列--- 第 78 页 ---78 | 鸿蒙 HarmonyOS NEXT 开发之路 卷2：从入门到应用篇GridRow({ columns: 8 }) {    ForEach(this.bgColors, (item: Color, index?: number | undefined) => {        GridCol() {            Row() {                Text(`${index}`)            }.width('100%').height('50')        }.backgroundColor(item)    })}.width('100%').height('100%').height(160).border(BorderWH).width('90%')}}显示效果如图 2-74 所示。当 columns 类型为 GridRowColumnOption 时，支持 6 种不同尺寸（xs, sm, md, lg, xl, xxl）设备的总列数设置，各个尺寸下的数值可不同，示例代码见文件 2-54。"
